class Solution {
public:
    vector<string> letterCombinations(string digits) {
        vector<string> result;
        if (digits.empty()) {
            return result;
        }

        unordered_map<char, string> phone_map = {
            {'2', "abc"},
            {'3', "def"},
            {'4', "ghi"},
            {'5', "jkl"},
            {'6', "mno"},
            {'7', "pqrs"},
            {'8', "tuv"},
            {'9', "wxyz"}
        };

        string current_combination;
        function<void(int)> backtrack = 
            [&](int index) {
            if (index == digits.length()) {
                result.push_back(current_combination);
                return;
            }

            char digit = digits[index];
            string letters = phone_map[digit];
            for (char letter : letters) {
                current_combination.push_back(letter);
                backtrack(index + 1);
                current_combination.pop_back(); // Backtrack
            }
        };

        backtrack(0);
        return result;
    }
};

