import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Solution {
    private List<String> result = new ArrayList<>();
    private Map<Character, String> phoneMap = new HashMap<>() {{
        put('2', "abc");
        put('3', "def");
        put('4', "ghi");
        put('5', "jkl");
        put('6', "mno");
        put('7', "pqrs");
        put('8', "tuv");
        put('9', "wxyz");
    }};

    public List<String> letterCombinations(String digits) {
        if (digits == null || digits.length() == 0) {
            return result;
        }

        backtrack(digits, 0, new StringBuilder());
        return result;
    }

    private void backtrack(String digits, int index, StringBuilder currentCombination) {
        // Base case: If the current combination's length equals the number of digits
        if (index == digits.length()) {
            result.add(currentCombination.toString());
            return;
        }

        char digit = digits.charAt(index);
        String letters = phoneMap.get(digit);

        // Iterate over the letters for the current digit
        for (char letter : letters.toCharArray()) {
            currentCombination.append(letter); // Choose
            backtrack(digits, index + 1, currentCombination); // Explore
            currentCombination.deleteCharAt(currentCombination.length() - 1); // Unchoose (backtrack)
        }
    }
}

