class Solution:
    def letterCombinations(self, digits: str) -> list[str]:
        if not digits:
            return []

        phone_map = {
            '2': "abc", '3': "def", '4': "ghi", '5': "jkl",
            '6': "mno", '7': "pqrs", '8': "tuv", '9': "wxyz"
        }

        result = []
        current_combination = [] # Using a list of chars for efficiency, then join

        def backtrack(index):
            # Base case: if the current combination is complete
            if index == len(digits):
                result.append("".join(current_combination))
                return

            digit = digits[index]
            letters = phone_map[digit]

            for letter in letters:
                current_combination.append(letter)  # Choose
                backtrack(index + 1)                # Explore
                current_combination.pop()           # Unchoose (backtrack)

        backtrack(0)
        return result

