/**
 * @param {string} digits
 * @return {string[]}
 */
var letterCombinations = function(digits) {
    if (!digits) {
        return [];
    }

    const phoneMap = {
        '2': 'abc',
        '3': 'def',
        '4': 'ghi',
        '5': 'jkl',
        '6': 'mno',
        '7': 'pqrs',
        '8': 'tuv',
        '9': 'wxyz'
    };

    const result = [];
    const currentCombination = [];

    function backtrack(index) {
        // Base case: If the current combination's length equals the number of digits
        if (index === digits.length) {
            result.push(currentCombination.join(''));
            return;
        }

        const digit = digits[index];
        const letters = phoneMap[digit];

        // Iterate over the letters for the current digit
        for (let i = 0; i < letters.length; i++) {
            currentCombination.push(letters[i]); // Choose
            backtrack(index + 1);             // Explore
            currentCombination.pop();           // Unchoose (backtrack)
        }
    }

    backtrack(0);
    return result;
};
